// How many entries reach the model; five leaves room for a buying-intent entry next to provider-type ones.
const RETRIEVED_ENTRIES = 5;
const STOP_WORDS = new Set('the and for are you your our with what how can does this that have has from about want need would like tell more into they them their its was were will just also any all not but who why when where which there here elixir software'.split(' '));
// Page context that another part of the site passes when it opens the assistant.
const PROVIDER_TYPE_SOURCES = {
  'online-behavioral-health': ['behavioral-health', 'telehealth', 'mental-health'],
  'treatment-center': ['treatment-center', 'addiction-treatment', 'behavioral-health'],
  cybhi: ['student-health-cybhi'],
  homecare: ['evv', 'caregiver-app', 'salesforce-evv'],
  'specialty-clinic': ['outpatient-clinics', 'small-practices', 'aesthetic-practices'],
};

export function isUsableEntry(entry, review = false) {
  return Boolean(entry) && (entry.status === 'approved' || (review && entry.status === 'draft')) && Boolean(entry.owner) && /^\d{4}-\d{2}-\d{2}$/.test(entry.reviewedAt ?? '') && typeof entry.content === 'string' && entry.content.length <= 3000 && /^https:\/\//.test(entry.url ?? '') && typeof entry.id === 'string';
}

// Visitor words match whole words in an entry (a plural "s" or "es" is ignored), so "car" does not
// match "care". For the production collection a single incidental body word (score 1) is below
// PRODUCTION_MIN_SCORE, so an off-topic question retrieves nothing and the chat handler uses the grounded
// fallback (overview plus discovery call) instead of an unrelated product page. Other collections have
// no such fallback in the handler, so they keep the minimum of 1.
const PRODUCTION_MIN_SCORE = 2;
const escapeRegExp = (text) => text.replace(/[.*+?^${}()|[\]\\/]/g, '\\$&');
const termPattern = (term) => new RegExp(`(?:^|[^a-z0-9])${escapeRegExp(term.length > 3 ? term.replace(/([^s])s$/, '$1') : term)}(?:e?s)?(?:$|[^a-z0-9])`);

/** Lower-cased visitor text with hyphenated words also present in their spaced form ("home-health" -> "home health"). */
function normalizeVisitorText(text) {
  const lower = String(text).toLowerCase();
  return `${lower} ${lower.replace(/([a-z0-9])-([a-z0-9])/g, '$1 $2')}`;
}

export function retrieveKnowledge(messages, entries = approvedKnowledge, { review = false, providerType = null, minScore = entries === approvedKnowledge ? PRODUCTION_MIN_SCORE : 1 } = {}) {
  const visitorMessages = messages.filter((message) => message.role === 'user');
  const visitorText = normalizeVisitorText(visitorMessages.slice(-3).map((message) => message.content).join(' '));
  // The newest message counts twice, so a new topic is not outranked by earlier turns.
  const latestText = normalizeVisitorText(visitorMessages.at(-1)?.content ?? '');
  const termsOf = (text) => [...new Set(text.match(/[a-z0-9][a-z0-9/-]{2,}/g) ?? [])].flatMap((term) => (term.includes('-') ? [term, ...term.split('-').filter((part) => part.length > 2)] : [term])).filter((term) => !STOP_WORDS.has(term)).slice(0, 100);
  const patterns = [...new Set(termsOf(visitorText))].map(termPattern);
  const latestPatterns = [...new Set(termsOf(latestText))].map(termPattern);
  const boosted = new Set(PROVIDER_TYPE_SOURCES[providerType] ?? []);
  return entries.filter((entry) => isUsableEntry(entry, review))
    .map((entry) => {
      const title = entry.title.toLowerCase();
      const body = entry.content.toLowerCase();
      const keywordMatches = (text) => (entry.keywords ?? []).filter((keyword) => new RegExp(`(?:^|[^a-z0-9])${escapeRegExp(keyword)}(?:$|[^a-z0-9])`).test(text) || (keyword.includes('-') && new RegExp(`(?:^|[^a-z0-9])${escapeRegExp(keyword.replaceAll('-', ' '))}(?:$|[^a-z0-9])`).test(text))).length;
      const termScoreOf = (list) => list.reduce((sum, pattern) => sum + (pattern.test(title) ? 3 : pattern.test(body) ? 1 : 0), 0);
      // The threshold applies to the conversation score alone; the newest-message bonus only reorders.
      const base = termScoreOf(patterns) + keywordMatches(visitorText) * 4;
      const score = base + termScoreOf(latestPatterns) + keywordMatches(latestText) * 4;
      const boost = base > 0 && boosted.has(entry.id) ? 3 : 0;
      return { entry, admitted: base + boost >= minScore, score: score + boost };
    })
    .filter(({ admitted }) => admitted)
    .sort((a, b) => b.score - a.score).slice(0, RETRIEVED_ENTRIES).map(({ entry }) => entry);
}

// Greeting and qualification-only turns still need grounded context: the overview, plus the pages
// that match where the visitor came from.
export function fallbackKnowledge(entries = approvedKnowledge, { review = false, providerType = null } = {}) {
  const usable = entries.filter((entry) => isUsableEntry(entry, review));
  const wanted = [...(PROVIDER_TYPE_SOURCES[providerType] ?? []).slice(0, 2), 'platform-overview', 'discovery-call'];
  const picked = wanted.map((id) => usable.find((entry) => entry.id === id)).filter(Boolean);
  return picked.length ? picked.slice(0, 4) : usable.slice(0, 1);
}
